const MicrosoftLogo = () => (
  <svg viewBox="0 0 24 24" fill="currentColor" width="100%" height="100%">
    <path d="M0 0h11.377v11.372H0zm12.623 0H24v11.372H12.623zM0 12.628h11.377V24H0zm12.623 0H24V24H12.623z" />
  </svg>
)

const brandConfig: Record<Certification['brand'], { logo: React.ElementType; color: string; label: string; logoW: string; logoH: string; textPad: string }> = {
  adobe:     { logo: AdobeLogo,     color: '#fa0f00', label: 'Adobe',     logoW: '72px', logoH: '39px', textPad: '84px' },
  github:    { logo: GitHubLogo,    color: 'var(--color-github-logo)', label: 'GitHub',    logoW: '88px', logoH: '25px', textPad: '100px' },
  microsoft: { logo: MicrosoftLogo, color: '#0078D4', label: 'Microsoft', logoW: '40px', logoH: '40px', textPad: '54px' },
}

const variants = {
  enter: (d: number) => ({ x: d * 50, opacity: 0 }),
  center: { x: 0, opacity: 1 },
  exit: (d: number) => ({ x: d * -50, opacity: 0 }),
}

export default function CertificationCarousel() {
  const [active, setActive] = useState(0)
  const [direction, setDirection] = useState(1)
  const [paused, setPaused] = useState(false)

  useEffect(() => {
    if (paused) return
    const timer = setInterval(() => {
      setDirection(1)
      setActive(prev => (prev + 1) % certifications.length)
    }, 3500)
    return () => clearInterval(timer)
  }, [paused])

  const goTo = (index: number) => {
    setDirection(index > active ? 1 : -1)
    setActive(index)
  }

  const cert = certifications[active]
  const { logo: Logo, color, label, logoW, logoH, textPad } = brandConfig[cert.brand]

  return (
    <div
      onMouseEnter={() => setPaused(true)}
      onMouseLeave={() => setPaused(false)}
    >
      <div className="cert-carousel-track">
        <AnimatePresence mode="wait" custom={direction}>
          <motion.a
            key={active}
            custom={direction}
            variants={variants}
            initial="enter"
            animate="center"
            exit="exit"
            transition={{ duration: 0.35, ease: [0.25, 0.1, 0.25, 1] }}
            href={cert.url}
            target="_blank"
            rel="noopener noreferrer"
            style={{
              display: 'block',
              padding: '1.5rem',
              border: '1px solid var(--color-border)',
              borderRadius: '10px',
              backgroundColor: 'var(--color-bg-subtle)',
              textDecoration: 'none',
              position: 'absolute',
              inset: 0,
              overflow: 'hidden',
              transition: 'border-color 0.2s',
            }}
            onMouseEnter={e => (e.currentTarget.style.borderColor = 'var(--color-accent-dark)')}
            onMouseLeave={e => (e.currentTarget.style.borderColor = 'var(--color-border)')}
          >
            {/* Brand logo watermark — top-right so it never overlaps text */}
            <div
              aria-hidden="true"
              style={{
                position: 'absolute',
                top: '1rem',
                right: '1rem',
                width: logoW,
                height: logoH,
                color: color,
                opacity: 0.75,
                pointerEvents: 'none',
                userSelect: 'none',
              }}
            >
              <Logo />
            </div>

            {/* Text content — padded right to clear the logo on all screen sizes */}
            <div style={{ paddingRight: textPad }}>
              <p style={{
                fontSize: '0.7rem',
                fontWeight: 600,
                textTransform: 'uppercase',
                letterSpacing: '0.1em',
                color: 'var(--color-text-faint)',
                marginBottom: '0.625rem',
              }}>
                {label} · {cert.type === 'course' ? 'Course' : 'Certification'}
              </p>

              <p style={{
                fontSize: '0.9375rem',
                fontWeight: 600,
                color: 'var(--color-text)',
                lineHeight: 1.45,
                marginBottom: '1rem',
              }}>
                {cert.name}
              </p>

              <span style={{
                fontSize: '0.8rem',
                color: 'var(--color-accent-text)',
                fontWeight: 500,
              }}>
                View credential ↗
              </span>
            </div>
          </motion.a>
        </AnimatePresence>
      </div>

      {/* Dot navigation */}
      <div style={{ display: 'flex', gap: 0, marginTop: '1.125rem', alignItems: 'center', justifyContent: 'center' }}>
        {certifications.map((cert, i) => (
          <button
            key={i}
            onClick={() => goTo(i)}
            aria-label={`Go to slide ${i + 1}: ${cert.name}`}
            aria-current={i === active ? true : undefined}
            style={{
              background: 'none',
              border: 'none',
              cursor: 'pointer',
              padding: '9px 4px',
              minWidth: '24px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
            }}
          >
            <span style={{
              display: 'block',
              width: i === active ? '20px' : '6px',
              height: '6px',
              borderRadius: '100px',
              backgroundColor: i === active ? 'var(--color-accent-dark)' : 'var(--color-border)',
              transition: 'width 0.3s, background-color 0.3s',
            }} />
          </button>
        ))}
      </div>
    </div>
  )
}
